#include <bits/stdc++.h>
using namespace std;

struct MathUtils {
    static long long extendedGCD(long long a, long long b, long long &x, long long &y) {
        if (a == 0) {
            x = 0; y = 1;
            return b;
        }
        long long x1, y1;
        long long gcd = extendedGCD(b % a, a, x1, y1);
        x = y1 - (b / a) * x1;
        y = x1;
        return gcd;
    }

    static long long inverse(long long a, long long mod) {
        long long x, y;
        long long g = extendedGCD(a, mod, x, y);
        if (g != 1) return 0;
        return (x % mod + mod) % mod;
    }

    static long long mod(long long a, long long m) {
        return ((a % m) + m) % m;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, M, K;
    cin >> N >> M >> K;
    const long long MOD = 998244353;
    long long invM = MathUtils::inverse(M, MOD);
    std::vector<long long> expect(K + 1, 0);
    std::vector<long long> poly(K + 1, 0);
    expect[0] = 1;
    poly[0] = 1;
    long long currentExpect = 1;

    for (int k = 1; k <= K; ++k) {
        long long numerator = 1;
        for (int i = 0; i < k; ++i) {
            numerator = (numerator * (N - i)) % MOD;
        }
        currentExpect = (numerator * invM) % MOD;

        for (int i = k; i >= 0; --i) {
            long long prevPoly = (i > 0) ? poly[i - 1] : 0;
            poly[i] = MathUtils::mod(prevPoly - (k - 1) * poly[i], MOD);
        }

        expect[k] = currentExpect;
        for (int i = k - 1; i >= 0; --i) {
            expect[k] = MathUtils::mod(expect[k] - poly[i] * expect[i], MOD);
        }
    }

    cout << expect[K] << "\n";

    return 0;
}
